def location(c, p, l, r):
	mid = (l + r) // 2
	if p[mid] > c and p[mid - 1] < c:
		return mid - 1
	elif p[mid - 1] > c:
		return location(c, p, l, mid)
	elif p[mid] < c:
		return location(c, p, mid, r)
for _ in range(int(input())):
	n = int(input())
	c = int(input())
	p = list(map(int, input().split()))
	p = sorted(p)
	if n == 1:
		if p[0] > c:
			l = -1
		else:
			l = 0
	elif n == 2:
		if p[0] > c:
			l = -1
		elif p[0] < c and p[1] > c:
			l = 0
		else:
			l = 1
	elif p[0] > c:
		l = -1
	elif p[-1] < c:
		l = n - 1
	else:
		l = location(c, p, 0, n)
	ans = 0
	xd = 1
	if l == -1:
		for i in range(n):
			if (c + p[i]) % 2 == 1:
				ans += 1
			else:
				xd = -1
				break
