			if (c + p[i]) % 2 == 1:
				a += 1
			else:
				xd = -1
				break
		for i in range(l + 1, n + 1):
			if (c + p[i]) % 2 == 1:
				b += 1
			else:
				xd = -1
				break
		ans = a + b
	print(ans, xd)
